pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1
        c.SetMinSum(1);
        // Initialize contract so SetMinSum cannot be called again
        c.Initialized();
        // Fund the test contract and send 1 wei via fallback/Put
        vm.deal(address(this), 1);
        (bool sent, ) = address(c).call{value: 1}("");
        require(sent, "send failed");
        // Warp past unlockTime (Put was called with _lockTime=0, so unlockTime = block.timestamp)
        vm.warp(block.timestamp + 1);
        // Try to Collect 1 wei — should succeed in reference (MinSum=1, balance=1, time passed)
        // In modified version, MinSum=0, so condition acc.balance >= MinSum is true, but MinSum is 0 not 1.
        // However the critical difference: in the reference the check is acc.balance >= MinSum (1 >= 1) true.
        // In modified, MinSum is 0, so condition is 1 >= 0 true, which is also true, so it seems same? 
        // Actually we need a scenario where the reference succeeds and modified fails because MinSum is different.
        // Let's use a different approach: after SetMinSum(1), the modified version has MinSum=0, reference has MinSum=1.
        // Collect requires balance >= MinSum. With balance=1, reference succeeds, modified also succeeds because 1 >= 0.
        // We need a case where reference's MinSum is higher than balance and modified's lower.
        // So set MinSum=2 in reference (via SetMinSum(2)), modified sets it to 0.
        // We'll deploy a new contract instance for clarity.
        // We'll redeploy in test body because setUp is fixed.
        c = new C();
        c.SetMinSum(2);
        c.Initialized();
        vm.deal(address(this), 1);
        (bool sent2, ) = address(c).call{value: 1}("");
        require(sent2);
        vm.warp(block.timestamp + 1);
        // Now balance=1, MinSum in reference=2, in modified=0. Collect should revert in reference (1 < 2) and succeed in modified.
        // But our assertion must PASS on reference and FAIL on modified.
        // So we assert that Collect reverts on reference (true) but it doesn't on modified (false).
        // We'll catch the revert.
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, Collect should revert (ok false). In modified, it should not revert (ok true).
        // We need the assertion to be true in reference, false in modified.
        // So we assert that ok is false. Reference: ok=false => assert(false) fails? Wait we need assertion PASSES on reference.
        // If we assert ok==false, reference passes (ok false), modified fails (ok true). That works.
        assertTrue(!ok);
    }
}

