        try c.Collect(1) {
            // If it succeeded, the assertion will catch it
            assertTrue(false); // We expect revert in reference
        } catch {
            // Expected revert: in reference, unlockTime=0, so timestamp>0 is true but balance<MinSum so condition false -> no revert but no action; actually Collect reverts if call fails? No, Collect only reverts if call fails; if condition false, it just does nothing. So we need different detection.
